package com.nigson.integration.carrier;
import java.time.*;
import java.util.*;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.integration.providers.CarrierProvider;
import com.nigson.shared.security.ProviderHttp;
/** Single cancellation attempt, followed exclusively by physical-piece reads and original receipt replay. */
public final class CarrierCancellationWorker {
 private final CarrierCancellationExecution execution;private final CarrierProvider provider;private final CarrierCancellationResultClient source;private final Clock clock;
 public CarrierCancellationWorker(CarrierCancellationExecution execution,CarrierProvider provider,CarrierCancellationResultClient source,Clock clock){this.execution=Objects.requireNonNull(execution);this.provider=Objects.requireNonNull(provider);this.source=Objects.requireNonNull(source);this.clock=Objects.requireNonNull(clock);}
 @Scheduled(fixedDelayString="${NIGSON_CARRIER_CANCELLATION_DELAY_MS:30000}",initialDelayString="${NIGSON_CARRIER_CANCELLATION_DELAY_MS:30000}")public void scheduled(){try{poll();}catch(RuntimeException unavailable){org.slf4j.LoggerFactory.getLogger(getClass()).warn("CARRIER_CANCELLATION_RECOVERY_REQUIRED");}}
 public int poll(){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");var claim=execution.claim();return claim.isEmpty()?0:process(claim.get());}
 public int process(CarrierCancellationExecution.Claim initial){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");var active=initial;try{if(active.pending()==null){String mode=provider.mode()==ProviderHttp.Mode.TEST?"SANDBOX":provider.mode().name();if(!mode.equals(active.command().mode())||!provider.accountFingerprint().equals(active.account())){var next=execution.outcome(active,"UNKNOWN","PROVIDER_MODE_MISMATCH",clock.instant());if(next.isEmpty())return 1;active=next.get();}else if(active.writable()){var next=execution.submitting(active);if(next.isEmpty()){execution.failed(active);return 1;}active=next.get();String state="UNKNOWN",reason="PROVIDER_OUTCOME_UNKNOWN";try{var output=provider.cancel(active.command().reference());if(output!=null&&output.path("cancelledShipment").isBoolean()){state=output.path("cancelledShipment").asBoolean()?"CANCELLED":"REJECTED";reason=state.equals("CANCELLED")?"NONE":"CARRIER_CANCEL_REJECTED";}}catch(ProviderHttp.Failure failure){if(!failure.uncertain&&failure.status>=400&&failure.status<500&&failure.status!=408){state="REJECTED";reason="CARRIER_CANCEL_REJECTED";}}catch(RuntimeException uncertain){/* A write may have been accepted: only read-only reconciliation follows. */}next=execution.outcome(active,state,reason,clock.instant());if(next.isEmpty())return 1;active=next.get();}else{var scans=new ArrayList<CarrierTrackingValues.Scan>();for(int i=0;i<active.pieces().size();i+=30){var batch=active.pieces().subList(i,Math.min(i+30,active.pieces().size()));scans.addAll(CarrierTrackingValues.parse(provider.track(batch),batch,clock.instant()));}var observation=CarrierTrackingValues.aggregate(scans,active.pieces().size());String state="CANCELLED".equals(observation.status())?"CANCELLED":"DELIVERED".equals(observation.status())?"REJECTED":"UNKNOWN";String reason=state.equals("CANCELLED")?"NONE":state.equals("REJECTED")?"CARRIER_ALREADY_DELIVERED":"PROVIDER_OUTCOME_UNKNOWN";var next=execution.outcome(active,state,reason,observation.occurredAt()==null?clock.instant():observation.occurredAt());if(next.isEmpty())return 1;active=next.get();}}source.acknowledge(active.pending());execution.acknowledged(active);return 1;}catch(RuntimeException unavailable){try{execution.failed(active);}catch(RuntimeException durable){org.slf4j.LoggerFactory.getLogger(getClass()).warn("CARRIER_CANCELLATION_LEASE_RECOVERY_REQUIRED");}return 1;}}
}
